{
  "tasks": [
    {
      "task_id": "T1",
      "title": "项目任务数量分布",
      "business_question": "各项目包含的任务数量是多少？",
      "priority": "P0",
      "priority_reason": "核心需求是探索主要分布，按项目分组统计任务是了解数据规模与分布的基础视角，删除后无法回答“哪些项目任务多”这一基本问题。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "sort",
          "params": {
            "field": "task_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "状态分布概览",
      "business_question": "不同状态下的任务数量分布如何？",
      "priority": "P0",
      "priority_reason": "状态是区分任务进展的关键维度，分析其分布能揭示工作流瓶颈或积压情况，属于“主要差异”的核心组成部分，删除后缺失对执行现状的基本洞察。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "status_task_count"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "工时统计概况",
      "business_question": "整体及分项目的平均工时表现如何？",
      "priority": "P1",
      "priority_reason": "工时是衡量投入的数值指标，虽然用户未指定具体统计口径（均值/中位数），但提供均值作为描述性分布有助于理解负载差异。若删除此任务，仅保留计数分布，分析质量会降低，缺少量化维度的对比。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              },
              {
                "function": "count",
                "field": "field_0004",
                "alias": "hours_record_count"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
